// arg is what an argument wrote, marked in the source's message for a
// pseudo locale.
func (msgs Messages) arg(s string) string {
	if msgs.mark {
		return i18n.Arg(s)
	}
	return s
}

// ActivitiesAddButton says "Add Activity"
// in the language the app shows under cx.
func ActivitiesAddButton(cx *core.Scope) string { return For(cx).ActivitiesAddButton() }

// ActivitiesAddButton is the package's ActivitiesAddButton in the language of msgs.
func (msgs Messages) ActivitiesAddButton() string { return msgs.text(textActivitiesAddButton) }

// ActivitiesCount says "{count} rows"
// in the language the app shows under cx.
//
// The number of activity rows, under the screen title.
func ActivitiesCount(cx *core.Scope, count int) string { return For(cx).ActivitiesCount(count) }

// ActivitiesCount is the package's ActivitiesCount in the language of msgs.
func (msgs Messages) ActivitiesCount(count int) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.ActivitiesCount(count))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].ActivitiesCount; f != nil {
			return f(count)
		}
		switch lang {
		case "", "en":
			return msgs.arg(i18n.FormatNumber("en", float64(count))) + " rows"
		case "zh-CN":
			return i18n.FormatNumber("zh-CN", float64(count)) + " 行"
		}
	}
}

// ActivitiesCreateFailed says "Failed to create activity"
// in the language the app shows under cx.
func ActivitiesCreateFailed(cx *core.Scope) string { return For(cx).ActivitiesCreateFailed() }

// ActivitiesCreateFailed is the package's ActivitiesCreateFailed in the language of msgs.
func (msgs Messages) ActivitiesCreateFailed() string { return msgs.text(textActivitiesCreateFailed) }

